/// bind:text on Entry: docs/notes/signals-and-slots-semantics.md 1.6 (gtk_sync_probe.py: set_text re-emits notify::text on identical text); renderer compares before set, the backend suppresses
#[test]
fn binding_entry_text() {
    on_gtk(|| {
        let mut h = Harness::new();
        let o = h.create("entry");
        let fire = |ob: &gtk::glib::Object, v: &str, i: usize| {
            let o = ob;
            let _ = (v, i);
            o.dynamic_cast_ref::<gtk::Editable>().unwrap().set_text(v);
        };
        h.listen(o, "changed", true).unwrap();
        fire(&h.obj(o), "hello", 0);
        fire(&h.obj(o), "hello2", 1);
        let ev = h.take_events_with_args();
        assert!(!ev.is_empty(), "native change is delivered");
        let arg = ev.last().unwrap().2.first().cloned().unwrap_or(V::Null);
        assert_eq!(arg, h.get(o, "text"), "the change signal's first argument is the new value");
    });
}

/// signal EventControllerFocus.enter: GtkEventControllerFocus::enter, run-last, void (Gtk 4 docs)
#[test]
fn signal_eventcontrollerfocus_enter() {
    on_gtk(|| {
        let mut h = Harness::new();
        let e = h.create("event-controller-focus");
        let o = e;
        
        let fire = |o: &gtk::glib::Object, v: &str, i: usize| {
            let _ = (v, i);
            let _ = (v, i); o.emit_by_name::<()>("enter", &[]);
        };
        assert_ne!(h.resolve_signal("event-controller-focus", "enter"), 0);
        assert_eq!(h.resolve_signal("event-controller-focus", "enter"), h.resolve_signal("event-controller-focus", "enter"));
        h.listen(e, "enter", true).unwrap();
        fire(&h.obj(e), "a", 0);
        // GTK may emit a signal several times per edit (e.g. delete + insert for set_text).
        let ev = h.take_events();
        assert!(!ev.is_empty() && ev.iter().all(|x| *x == (e, "enter".to_string())), "delivered: {ev:?}");
        h.listen(e, "enter", false).unwrap();
        fire(&h.obj(e), "b", 1);
        assert!(h.take_events().is_empty(), "no delivery after listen(off)");
        h.listen(e, "enter", true).unwrap();
        let obj = h.obj(e);
        h.destroy(e);
        fire(&obj, "c", 2);
        assert!(h.take_events().is_empty(), "handler is disconnected on destroy");
        assert!(h.listen(e, "enter", true).is_err(), "stale handle is an error");
    });
}

